def main():
    for code, values in T.items():
        assert len(values) == len(KEYS), (code, len(values), len(KEYS))
        path = os.path.join(ROOT, "src", "JunkCleanup", "Localization", "Strings", f"{code}.json")
        with open(path, encoding="utf-8-sig") as f:
            strings = json.load(f)
        strings.update(dict(zip(KEYS, values)))
        for item_id, (name, desc) in zip(WIN_IDS, WIN[code]):
            strings[f"space.{item_id}.name"] = name
            strings[f"space.{item_id}.desc"] = desc
        with open(path, "w", encoding="utf-8") as f:
            json.dump(strings, f, ensure_ascii=False, indent=2)
            f.write("\n")
    print(f"updated {len(T)} languages with {len(KEYS)} keys")

if __name__ == "__main__":
    main()
